import { type DependencyList, type EffectCallback, type MouseEvent, type ReactNode } from 'react';
export interface FieldWrapperProps {
    id?: string;
    children: ReactNode;
    description?: string;
    label?: string;
    onContextMenu?: (event: MouseEvent) => void;
    onReset?: (event: MouseEvent) => void;
    enable?: boolean;
    enableReset?: boolean;
    disabledDescription?: string;
    hasSync?: boolean;
    isSynced?: boolean;
    onUnsyncGlobalModuleAttribute?: () => void;
    /**
     * Callback function to be called when dependencyList value changes.
     */
    dependencyCallback?: EffectCallback;
    /**
     * Dependency list for dependencyCallback. The change of value of this prop will execute dependencyCallback.
     */
    dependencyList?: DependencyList;
}
